#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
patch_freight_row.py — Kit 29d ([freight-row] — صف الفريت الرسمي)
==================================================================
freightCalculateTip كان كيرجع 200 بقنوات خاوية بلا سبب. السبب:
صف الطلب ما كانش مطابق للـ CURL الرسمي — productProp خاصو تكون
مصفوفة، و freightTrialSkuList + skuList + volume = Required(Y).

الحل (v3.3):
  · صف الطلب طبق الأصل من التوثيق الرسمي (1.2 freightCalculateTip)
  · القنوات خاويين؟ → 1.3 unavailableShippingMethods بنفس الـ payload
    → shipping.unavailable = أسباب CJ الرسمية (2015/2013/2008/...)
  · ?debug=1 كيفثّح freightDebug (الصف المرسل + env + عدد القنوات)
  · كاش سلبي 10 دقائق للنتيجة الخاوية — حماية النقاط

يخدم من جذر الـ backend (الفولدر اللي فيه server.js).
Backup: routes/cjLiveBridge.js.bak-kit29d — Idempotent.
"""
import base64, os, shutil, sys

FILES = {"backend/routes/cjLiveBridge.js": "", "verify_live_pipeline.py": ""}
BACKUP = ".bak-kit29d"
B = lambda name: base64.b64decode(FILES[name]).decode("utf-8")

def detect_tree():
    if os.path.exists("server.js") and os.path.exists("routes"):
        return "backend"
    return None

def main():
    if detect_tree() != "backend":
        print("❌ شغل هاد السكريبت من جذر الـ BACKEND (الفولدر اللي فيه server.js)")
        sys.exit(1)

    p = "routes/cjLiveBridge.js"
    if not os.path.exists(p):
        print(f"❌ {p} ما كاينش — ركب Kit 29 (Geo Flow) الأول")
        sys.exit(1)

    src = open(p, encoding="utf-8").read()
    if "[freight-row]" in src:
        print("✓ cjLiveBridge.js — رقعة kit29d مركبة مسبقاً (skip — idempotent)")
        return

    bak = p + BACKUP
    if not os.path.exists(bak):
        shutil.copy2(p, bak)
        print(f"♻ backup → {bak}")
    else:
        print(f"ℹ backup قديم محفوظ ({bak})")

    write(p, B("backend/routes/cjLiveBridge.js"))

    chk = open(p, encoding="utf-8").read()
    if "[freight-row]" not in chk:
        print("❌ فحص بعد الكتابة فشل — المجلة ما فيهاش الرقعة!")
        sys.exit(1)
    print("✚ routes/cjLiveBridge.js — v3.3 (صف الفريت الرسمي + 1.3 diagnostic + debug=1)")
    print("  [NEXT] commit + push → Render redeploy → python verify_live_pipeline.py")

def write(path, content):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(content)

if __name__ == "__main__":
    main()
